import React from 'react';
import { Search, Filter, ChevronRight, CheckCircle2, Clock, AlertTriangle } from 'lucide-react';

export function LedgerTable({ inspections, onSelect }) {
  return (
    <div className="bg-white border border-slate-200 rounded-xl overflow-hidden shadow-sm">
      <div className="p-4 border-b border-slate-200 flex justify-between items-center bg-slate-50">
        <div className="relative w-72">
          <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
          <input 
            type="text" 
            placeholder="Search by ID or product..." 
            className="w-full bg-white border border-slate-200 text-sm text-slate-700 rounded-lg pl-9 pr-4 py-2 focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 outline-none transition-all" 
          />
        </div>
        <button className="flex items-center space-x-2 px-3 py-2 border border-slate-200 text-slate-600 bg-white rounded-lg hover:bg-slate-50 transition-colors text-sm font-medium">
          <Filter className="w-4 h-4" />
          <span>Filter</span>
        </button>
      </div>
      
      <div className="overflow-x-auto">
        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="bg-white text-slate-500 text-xs uppercase tracking-wider border-b border-slate-200">
              <th className="py-3.5 px-6 font-semibold">Date / ID</th>
              <th className="py-3.5 px-6 font-semibold">Product</th>
              <th className="py-3.5 px-6 font-semibold">Verdict</th>
              <th className="py-3.5 px-6 font-semibold">OCR Confidence</th>
              <th className="py-3.5 px-6 font-semibold text-right">Action</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {inspections.map((insp) => (
              <tr 
                key={insp.id} 
                className="hover:bg-slate-50/80 transition-colors cursor-pointer group" 
                onClick={() => onSelect(insp)}
              >
                <td className="py-3.5 px-6">
                  <p className="text-slate-900 font-medium text-sm">{new Date(insp.created_at).toLocaleDateString()}</p>
                  <p className="text-xs text-slate-500 font-mono mt-0.5">LM-{insp.id.substring(0,6)}</p>
                </td>
                <td className="py-3.5 px-6">
                  <p className="text-slate-800 font-medium text-sm">{insp.product_name || 'Unknown SKU'}</p>
                  <p className="text-xs text-slate-500 mt-0.5">{insp.brand_name || 'Unknown Brand'}</p>
                </td>
                <td className="py-3.5 px-6">
                  <span className={`inline-flex items-center px-2.5 py-1 rounded-full text-[11px] font-semibold border ${
                    insp.verdict === 'Likely Compliant' ? 'bg-emerald-50 text-emerald-700 border-emerald-200' :
                    insp.verdict === 'Needs Officer Review' ? 'bg-amber-50 text-amber-700 border-amber-200' :
                    'bg-rose-50 text-rose-700 border-rose-200'
                  }`}>
                    {insp.verdict === 'Likely Compliant' && <CheckCircle2 className="w-3.5 h-3.5 mr-1.5" />}
                    {insp.verdict === 'Needs Officer Review' && <Clock className="w-3.5 h-3.5 mr-1.5" />}
                    {insp.verdict === 'Likely Violation' && <AlertTriangle className="w-3.5 h-3.5 mr-1.5" />}
                    {insp.verdict}
                  </span>
                </td>
                <td className="py-3.5 px-6">
                  <div className="flex items-center">
                    <div className="w-16 h-1.5 bg-slate-100 rounded-full mr-3 overflow-hidden border border-slate-200/50">
                      <div 
                        className={`h-full rounded-full ${insp.ocr_confidence > 0.7 ? 'bg-emerald-500' : 'bg-amber-500'}`} 
                        style={{width: `${insp.ocr_confidence * 100}%`}}
                      ></div>
                    </div>
                    <span className="text-xs text-slate-600 font-medium">{(insp.ocr_confidence * 100).toFixed(0)}%</span>
                  </div>
                </td>
                <td className="py-3.5 px-6 text-right">
                  <button className="text-blue-600 hover:text-blue-800 text-sm font-medium flex items-center justify-end w-full group-hover:translate-x-1 transition-transform">
                    View Dossier <ChevronRight className="w-4 h-4 ml-1" />
                  </button>
                </td>
              </tr>
            ))}
            {inspections.length === 0 && (
              <tr>
                <td colSpan="5" className="py-12 px-6 text-center text-slate-500">
                  <div className="flex flex-col items-center justify-center">
                    <Search className="w-8 h-8 text-slate-300 mb-3" />
                    <p className="text-sm">No inspections found in the repository.</p>
                  </div>
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}
