"use client";

import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { toast } from 'sonner';

import { Header } from '@/components/layout/Header';
import { Sidebar } from '@/components/layout/Sidebar';
import { StatCards } from '@/components/dashboard/StatCards';
import { Charts } from '@/components/dashboard/Charts';
import { IngestionDropzone } from '@/components/upload/IngestionDropzone';
import { LedgerTable } from '@/components/inspections/LedgerTable';
import { InspectionDetail } from '@/components/inspections/InspectionDetail';
import { ShieldCheck, Lock } from 'lucide-react';

const API_BASE = 'http://localhost:8000';

export default function MetroScanApp() {
  const [token, setToken] = useState(null);
  const [user, setUser] = useState(null);
  const [loginEmail, setLoginEmail] = useState('');
  const [loginPassword, setLoginPassword] = useState('');
  const [isLoggingIn, setIsLoggingIn] = useState(false);

  const [activeTab, setActiveTab] = useState('dashboard');
  
  const [stats, setStats] = useState({
    total_scanned: 0,
    compliance_rate: 0,
    violations_by_rule: {},
    needs_review_count: 0,
    likely_violation_count: 0
  });
  
  const [inspections, setInspections] = useState([]);
  const [selectedInspection, setSelectedInspection] = useState(null);
  
  const [isUploading, setIsUploading] = useState(false);

  // Setup Axios interceptor
  useEffect(() => {
    if (token) {
      axios.defaults.headers.common['Authorization'] = `Bearer ${token}`;
      fetchData();
    } else {
      delete axios.defaults.headers.common['Authorization'];
    }
  }, [token]);

  const fetchData = async () => {
    try {
      const [statsRes, inspRes] = await Promise.all([
        axios.get(`${API_BASE}/dashboard/stats`),
        axios.get(`${API_BASE}/inspections`)
      ]);
      setStats(statsRes.data);
      setInspections(inspRes.data);
    } catch (e) {
      toast.error("Failed to sync dashboard data.");
    }
  };

  const handleLogin = async (e) => {
    e.preventDefault();
    setIsLoggingIn(true);
    try {
      const formData = new URLSearchParams();
      formData.append('username', loginEmail);
      formData.append('password', loginPassword);
      
      const res = await axios.post(`${API_BASE}/token`, formData, {
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' }
      });
      
      const accessToken = res.data.access_token;
      setToken(accessToken);
      
      // Decode JWT
      const base64Url = accessToken.split('.')[1];
      const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
      const payload = JSON.parse(window.atob(base64));
      setUser(payload);
      
      toast.success("Successfully authenticated to DoCA Server");
      
      if (payload.role === 'Supervisor') {
        setActiveTab('inspections');
      }
    } catch (e) {
      toast.error('Authentication failed. Check your credentials.');
    } finally {
      setIsLoggingIn(false);
    }
  };

  const handleLogout = () => {
    setToken(null);
    setUser(null);
    setActiveTab('dashboard');
    toast.info("Session terminated securely.");
  };

  const handleUpload = async (file) => {
    setIsUploading(true);
    const formData = new FormData();
    formData.append('file', file);
    
    try {
      const toastId = toast.loading("Ingesting file and running AI analysis...");
      
      if (activeTab === 'single_scan') {
        formData.append('product_name', 'Uploaded Product');
        formData.append('brand_name', 'Uploaded Brand');
        await axios.post(`${API_BASE}/scan/single`, formData);
      } else {
        await axios.post(`${API_BASE}/scan/bulk`, formData);
      }
      
      await fetchData();
      setActiveTab('inspections');
      toast.success("Ingestion successful. AI evaluation complete.", { id: toastId });
    } catch (e) {
      toast.error('Ingestion failed: ' + (e.response?.data?.detail || e.message));
      throw e;
    } finally {
      setIsUploading(false);
    }
  };

  const handleExport = (id, format) => {
    window.open(`${API_BASE}/inspections/${id}/export?format=${format}&token=${token}`, '_blank');
    toast.success(`${format.toUpperCase()} memo generated.`);
  };

  const handleSignOff = async (id) => {
    try {
      await axios.post(`${API_BASE}/inspections/${id}/sign-off`);
      toast.success("Violation electronically signed and confirmed.");
      await fetchData();
      setSelectedInspection({...selectedInspection, verdict: 'Likely Violation'});
    } catch (e) {
      toast.error("Sign-off authorization failed.");
    }
  };

  // Login View
  if (!token) {
    return (
      <div className="min-h-screen bg-slate-50 text-slate-800 flex items-center justify-center p-4">
        <div className="max-w-md w-full bg-white border border-slate-200 rounded-2xl p-8 shadow-xl relative overflow-hidden">
          {/* Header Strip */}
          <div className="absolute top-0 left-0 w-full h-1.5 bg-gradient-to-r from-[#FF9933] via-white to-[#138808]"></div>
          
          <div className="flex flex-col items-center justify-center mb-8 text-center mt-4">
            <div className="w-14 h-14 rounded-xl bg-blue-50 text-blue-700 flex items-center justify-center border border-blue-100 shadow-sm mb-4">
              <ShieldCheck className="w-8 h-8" />
            </div>
            <h1 className="text-2xl font-bold text-slate-900 tracking-tight">METROSCAN AI</h1>
            <p className="text-sm text-slate-500 font-medium mt-1">Ministry of Consumer Affairs</p>
            <p className="text-xs text-slate-400 mt-0.5">Secure Officer Gateway</p>
          </div>
          
          <form onSubmit={handleLogin} className="space-y-5">
            <div>
              <label className="text-sm font-semibold text-slate-700 mb-1.5 block">Official Email Address</label>
              <input 
                type="email" 
                value={loginEmail} 
                onChange={(e) => setLoginEmail(e.target.value)} 
                className="w-full bg-white border border-slate-300 text-slate-900 rounded-lg px-4 py-2.5 focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 outline-none transition-all" 
                placeholder="officer@doca.gov.in" 
                required 
              />
            </div>
            <div>
              <label className="text-sm font-semibold text-slate-700 mb-1.5 block">Passcode</label>
              <input 
                type="password" 
                value={loginPassword} 
                onChange={(e) => setLoginPassword(e.target.value)} 
                className="w-full bg-white border border-slate-300 text-slate-900 rounded-lg px-4 py-2.5 focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 outline-none transition-all" 
                placeholder="••••••••" 
                required 
              />
            </div>
            <button 
              type="submit" 
              disabled={isLoggingIn}
              className="w-full bg-blue-600 hover:bg-blue-700 text-white font-semibold py-3 rounded-lg shadow-sm transition-colors flex justify-center items-center mt-2 disabled:opacity-70"
            >
              {isLoggingIn ? 'Authenticating...' : <><Lock className="w-4 h-4 mr-2" /> Secure Login</>}
            </button>
          </form>
          
          <div className="mt-8 text-center text-xs text-slate-500 bg-slate-50 p-4 rounded-lg border border-slate-100">
            <p className="font-semibold text-slate-600 mb-2">Internal Demo Accounts</p>
            <div className="space-y-1">
              <p>inspector@doca.gov.in (Upload/Export)</p>
              <p>supervisor@doca.gov.in (Review/Sign-off)</p>
              <p>admin@doca.gov.in (Superuser Access)</p>
            </div>
            <p className="mt-2 text-slate-400">Passcode: Pass@123</p>
          </div>
        </div>
      </div>
    );
  }

  const canSignOff = user?.role === 'Supervisor' || user?.role === 'Admin';

  // App Layout
  return (
    <div className="h-screen flex flex-col bg-slate-50 font-sans text-slate-900 overflow-hidden">
      <Header user={user} onLogout={handleLogout} />
      
      <div className="flex flex-1 overflow-hidden">
        <Sidebar activeTab={activeTab} setActiveTab={(tab) => {
          setActiveTab(tab);
          if (tab !== 'inspections') setSelectedInspection(null);
        }} user={user} />

        <main className="flex-1 overflow-y-auto p-8 scroll-smooth">
          <div className="max-w-6xl mx-auto w-full">
            
            {activeTab === 'dashboard' && (
              <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
                <div className="mb-8">
                  <h2 className="text-2xl font-bold text-slate-900">Compliance Overview</h2>
                  <p className="text-sm text-slate-500">Real-time telemetry from the Rule 6 and Rule 12 verification engine.</p>
                </div>
                <StatCards stats={stats} />
                <Charts stats={stats} />
              </div>
            )}

            {activeTab === 'single_scan' && (
              <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 h-full flex items-center justify-center">
                <IngestionDropzone onUpload={handleUpload} isUploading={isUploading} mode="single" />
              </div>
            )}

            {activeTab === 'bulk_ingestion' && (
              <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 h-full flex items-center justify-center">
                <IngestionDropzone onUpload={handleUpload} isUploading={isUploading} mode="bulk" />
              </div>
            )}

            {activeTab === 'inspections' && !selectedInspection && (
              <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
                <div className="mb-6 flex justify-between items-end">
                  <div>
                    <h2 className="text-2xl font-bold text-slate-900">Inspection Repository</h2>
                    <p className="text-sm text-slate-500 mt-1">Immutable ledger of all AI compliance evaluations.</p>
                  </div>
                </div>
                <LedgerTable 
                  inspections={inspections} 
                  onSelect={(insp) => setSelectedInspection(insp)} 
                />
              </div>
            )}

            {activeTab === 'inspections' && selectedInspection && (
              <InspectionDetail 
                inspection={selectedInspection} 
                onBack={() => setSelectedInspection(null)}
                onSignOff={handleSignOff}
                onExport={handleExport}
                canSignOff={canSignOff}
              />
            )}
            
            {activeTab === 'analytics' && (
               <div className="flex flex-col items-center justify-center h-full text-slate-400">
                  <span className="text-4xl mb-4">📈</span>
                  <h3 className="text-xl font-semibold text-slate-700">Analytics Sandbox</h3>
                  <p className="text-sm mt-2">Advanced reporting models are currently being trained.</p>
               </div>
            )}
            
            {activeTab === 'settings' && (
               <div className="flex flex-col items-center justify-center h-full text-slate-400">
                  <span className="text-4xl mb-4">⚙️</span>
                  <h3 className="text-xl font-semibold text-slate-700">Platform Settings</h3>
                  <p className="text-sm mt-2">Configuration is restricted to IT Directorate.</p>
               </div>
            )}

          </div>
        </main>
      </div>
    </div>
  );
}
