import React from 'react';
import { cn } from '@/lib/utils';
import { 
  LayoutDashboard, 
  Upload, 
  ScanLine, 
  Archive, 
  BarChart3, 
  Settings 
} from 'lucide-react';

export function Sidebar({ activeTab, setActiveTab, user }) {
  
  const canUpload = user?.role === 'Inspector' || user?.role === 'Admin';
  
  const navItems = [
    { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard },
    { id: 'single_scan', label: 'Single Scan', icon: ScanLine, hidden: !canUpload },
    { id: 'bulk_ingestion', label: 'Bulk Ingestion', icon: Upload, hidden: !canUpload },
    { id: 'inspections', label: 'Inspection Repository', icon: Archive },
    { id: 'analytics', label: 'Compliance Analytics', icon: BarChart3 },
    { id: 'settings', label: 'Settings', icon: Settings },
  ];

  return (
    <div className="w-64 border-r border-slate-200 bg-white flex flex-col justify-between shrink-0 h-full">
      <div className="py-6 px-4">
        <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-4 px-2">Navigation</p>
        <nav className="space-y-1">
          {navItems.map((item) => {
            if (item.hidden) return null;
            const isActive = activeTab === item.id;
            return (
              <button
                key={item.id}
                onClick={() => setActiveTab(item.id)}
                className={cn(
                  "w-full flex items-center px-3 py-2.5 rounded-lg text-sm transition-all duration-200 group",
                  isActive 
                    ? "bg-blue-50 text-blue-700 font-medium shadow-sm border border-blue-100" 
                    : "text-slate-600 hover:bg-slate-50 hover:text-slate-900 border border-transparent"
                )}
              >
                <item.icon className={cn("w-4 h-4 mr-3", isActive ? "text-blue-600" : "text-slate-400 group-hover:text-slate-600")} />
                {item.label}
              </button>
            )
          })}
        </nav>
      </div>
      
      <div className="p-4 border-t border-slate-100">
        <div className="bg-slate-50 border border-slate-200 rounded-lg p-4 text-center">
          <p className="text-xs font-medium text-slate-700 mb-1">METROSCAN AI v2.0</p>
          <p className="text-[10px] text-slate-500">Civic-Tech Edition</p>
        </div>
      </div>
    </div>
  );
}
